    void updateHeader(TvRows.Tile tile){if(backdrop==null)return;if(headerTask!=null)ui.removeCallbacks(headerTask);headerTask=()->{if(backdrop==null||!page.equals("Home")||isDestroyed())return;JSONObject i=tile.item;headerTitle.setText(tile.title());List<String> meta=new ArrayList<>();String year=i.optString("year",tile.discover==null?"":tile.discover.optString("releaseInfo"));if(!year.isEmpty()&&!year.equals("0"))meta.add(year);if(tile.discover==null&&!i.optBoolean("movie"))meta.add(MainActivity.episode(i));double runtime=i.optDouble("duration",0)/60;if(runtime<=0)runtime=i.optDouble("runtime",0);if(runtime>0)meta.add((int)Math.ceil(runtime)+" "+Loc.t("min"));else{Set<String> genres=HomeLayout.genre(i);if(!genres.isEmpty())meta.add(String.join(" · ",genres));}headerMeta.setText(String.join(" · ",meta));String summary=i.optString("summary",i.optString("description"));if(summary.isEmpty()&&(!model.settings.optBoolean("hideSpoilers",true)||DataStore.watched(i)))summary=i.optString("episodeSummary");headerSummary.setText(android.text.Html.fromHtml(summary,android.text.Html.FROM_HTML_MODE_LEGACY).toString());TvUi.load(backdrop,safeArt(i),true,dp(780),dp(260));};ui.postDelayed(headerTask,150);}
    JSONObject safeArt(JSONObject item){if(!model.settings.optBoolean("hideSpoilers",true)||DataStore.watched(item)||item.optString("episodeImage").isEmpty())return item;JSONObject copy=DataStore.copy(item);DataStore.put(copy,"episodeImage","");return copy;}
