    void focusRail(){int n=Arrays.asList(pages).indexOf(page);nav.get(Math.max(0,n)).requestFocus();}
    void returnToContent(){restoreFocus(false);}
    void restoreFocus(boolean edit){if(model==null){focusRail();return;}final String current=page;ui.post(()->{if(isDestroyed()||model==null||body==null||!page.equals(current))return;if(edit&&input!=null){input.requestFocus();return;}Memory m=memory();RowViews pick=null;for(RowViews row:visibleRows)if(row.id.equals(m.row)){pick=row;break;}if(pick==null&&!visibleRows.isEmpty())pick=visibleRows.get(0);if(pick!=null&&!pick.tiles.isEmpty()){int index=Math.min(m.index,pick.tiles.size()-1);for(int n=0;n<pick.values.size();n++)if(pick.values.get(n).key.equals(m.tile)){index=n;break;}pick.tiles.get(Math.max(0,index)).requestFocus();settle(pick);}else if(input!=null)input.requestFocus();else if(body.getChildCount()==0||!body.getChildAt(0).requestFocus(View.FOCUS_DOWN))focusRail();});}
    void emptyHome(){LinearLayout card=column();card.setPadding(dp(22),dp(18),dp(22),dp(20));card.setBackground(TvUi.bg(TvUi.PANEL,dp(14)));TextView title=text("Your next great watch starts here",22,TvUi.WHITE,true);title.setPadding(0,0,0,dp(18));card.addView(title);LinearLayout buttons=new LinearLayout(this);TextView pair=TvUi.button(this,Loc.t("Pair with your PC"),true,()->startActivity(new Intent(this,TvSetupActivity.class))),settings=TvUi.button(this,Loc.t("Settings"),false,()->startActivity(new Intent(this,TvSettingsActivity.class)));buttons.addView(pair,tileParams());buttons.addView(settings);card.addView(buttons);card.setTag("empty");body.addView(card);pair.setOnKeyListener((v,k,e)->{if(k==toRail()){if(e.getAction()==KeyEvent.ACTION_DOWN)focusRail();return true;}return false;});}
    void buildSearch(){
        input=new EditText(this);input.setSingleLine(true);input.setTextColor(TvUi.WHITE);input.setHintTextColor(TvUi.MUTED);input.setTextSize(18);input.setHint(Loc.t("Search movies and shows"));input.setPadding(dp(16),dp(10),dp(16),dp(10));input.setBackground(TvUi.bg(TvUi.PANEL,dp(9)));input.setText(query);input.setSelectAllOnFocus(false);input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT);pageRoot.addView(input,new LinearLayout.LayoutParams(-1,dp(52)));
        input.setOnClickListener(v->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT));input.setOnEditorActionListener((v,action,e)->{hideKeyboard();if(!visibleRows.isEmpty())visibleRows.get(0).tiles.get(0).requestFocus();return true;});
        input.setOnKeyListener((v,k,e)->{if(k==KeyEvent.KEYCODE_DPAD_DOWN){if(e.getAction()==KeyEvent.ACTION_DOWN&&!visibleRows.isEmpty()){hideKeyboard();visibleRows.get(0).tiles.get(0).requestFocus();}return true;}if(k==toRail()&&searchCursorAtRailEdge()){if(e.getAction()==KeyEvent.ACTION_DOWN)focusRail();return true;}return false;});
        input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();remoteSearchTiles.clear();remoteQuery="";searchGeneration++;if(searchFuture!=null)searchFuture.cancel(true);body.removeAllViews();visibleRows.clear();memory().row="";memory().tile="";memory().index=0;gridTiles=new ArrayList<>(model.search(query));gridCount=0;more=null;appendGrid();scheduleSearch();}});
        searchStatus=text("Type a title or use your remote microphone",13,TvUi.MUTED,false);searchStatus.setPaddingRelative(dp(4),dp(6),0,dp(5));pageRoot.addView(searchStatus);
    }
    int columns(){return Math.max(1,(getResources().getConfiguration().screenWidthDp-48*2-72-28)/(TvUi.POSTER_W+8+14));}
    List<TvRows.Tile> searchTiles(){List<TvRows.Tile> tiles=new ArrayList<>(model.search(query));if(query.trim().equals(remoteQuery)){JSONArray remote=new JSONArray();for(TvRows.Tile t:remoteSearchTiles)remote.put(t.discover);tiles.addAll(TvRows.discovered(remote,model));}return tiles;}
    void refreshSearch(){boolean editing=input.hasFocus(),navFocused=inside(rail,getCurrentFocus()),paging=more!=null&&more.hasFocus();restoring=true;body.removeAllViews();visibleRows.clear();more=null;gridTiles=searchTiles();gridCount=0;appendGrid();restoring=false;scheduleSearch();if(!editing&&!navFocused){if(paging&&more!=null)more.requestFocus();else restoreFocus(false);}}
    void appendGrid(){
        if(more!=null){body.removeView(more);more=null;}if(body.getChildCount()==1&&"empty-grid".equals(body.getChildAt(0).getTag()))body.removeAllViews();
        int cols=columns(),end=Math.min(gridTiles.size(),gridCount+cols*10);if(gridCount==0&&!memory().tile.isEmpty())for(int n=0;n<gridTiles.size();n++)if(gridTiles.get(n).key.equals(memory().tile)){end=Math.max(end,Math.min(gridTiles.size(),(n/cols+1)*cols));break;}while(gridCount<end){RowViews row=null;if(!visibleRows.isEmpty()){RowViews last=visibleRows.get(visibleRows.size()-1);if(last.grid&&last.tiles.size()<cols)row=last;}if(row==null){row=new RowViews("grid:"+visibleRows.size());row.grid=true;LinearLayout strip=new LinearLayout(this);strip.setClipChildren(false);strip.setPadding(0,dp(12),0,dp(10));row.view=strip;visibleRows.add(row);body.addView(strip);}TvRows.Tile value=gridTiles.get(gridCount++);View tile=tile(value,false,false,row,row.tiles.size());((LinearLayout)row.view).addView(tile,tileParams());}
        if(gridCount<gridTiles.size()){TextView button=TvUi.button(this,Loc.t("More titles"),false,()->{int first=visibleRows.size();appendGrid();if(visibleRows.size()>first)visibleRows.get(first).tiles.get(0).requestFocus();});more=button;body.addView(button);}
        if(gridTiles.isEmpty())emptyGrid();
    }
    // Empty pages say what fills them and offer a focusable way on, so focus never strands on the rail.
    void emptyGrid(){
        boolean search=page.equals("Search");if(search&&query.trim().isEmpty())return;String title=search?"No results yet":page.equals("My List")?"Nothing in My List yet":page.equals("Ready")?"Nothing ready offline yet":"Nothing here yet",note=search?"Try another title or spelling.":page.equals("My List")?"Open any title and choose ＋ My List to save it here.":page.equals("Ready")?"Titles stored on this TV show up here. Everything else plays from your PC or streams.":"";
        LinearLayout card=column();card.setPadding(dp(10),dp(24),dp(10),0);card.setTag("empty-grid");card.addView(text(title,19,TvUi.WHITE,true));if(!note.isEmpty()){TextView sub=text(note,15,TvUi.MUTED,false);sub.setPadding(0,dp(8),0,dp(16));card.addView(sub);}
        if(!search&&!page.startsWith("shelf:")){LinearLayout buttons=new LinearLayout(this);TextView find=TvUi.button(this,Loc.t("Search"),true,()->showPage("Search",true)),home=TvUi.button(this,Loc.t("Home"),false,()->showPage("Home",true));buttons.addView(find,tileParams());buttons.addView(home);card.addView(buttons);find.setOnKeyListener((v,k,e)->{if(k==toRail()){if(e.getAction()==KeyEvent.ACTION_DOWN)focusRail();return true;}return false;});}
        body.addView(card);
    }
    void scheduleSearch(){if(searchTask!=null)ui.removeCallbacks(searchTask);int token=++searchGeneration;String q=query.trim();if(q.isEmpty()){if(searchStatus!=null)searchStatus.setText(Loc.t("Type a title or use your remote microphone"));return;}searchStatus.setText(Loc.t("Searching Discover…"));DataStore source=data;TvRows local=model;searchTask=()->{searchFuture=searches.submit(()->{try{JSONArray result=new DiscoveryClient(source.context).search(q,"All");List<TvRows.Tile> remote=TvRows.discovered(result,local);ui.post(()->{if(isDestroyed()||source!=data||token!=searchGeneration||!page.equals("Search"))return;remoteQuery=q;remoteSearchTiles=new ArrayList<>(remote);Set<String> seen=new HashSet<>();for(TvRows.Tile t:gridTiles)seen.add(t.key);for(TvRows.Tile t:remote)if(seen.add(t.key))gridTiles.add(t);if(more==null)appendGrid();searchStatus.setText("");});}catch(Exception ignored){ui.post(()->{if(!isDestroyed()&&token==searchGeneration&&page.equals("Search"))searchStatus.setText(Loc.t("Discover is temporarily unavailable"));});}});};ui.postDelayed(searchTask,400);}
    void hideKeyboard(){if(input!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);}
    void appendDiscover(){if(body==null||!page.equals("Home"))return;Set<String> shown=new HashSet<>();for(RowViews r:visibleRows)shown.add(r.id);for(TvRows.Row r:discoveryRows.values())if(!shown.contains(r.id)&&!r.tiles.isEmpty()){boolean empty=visibleRows.isEmpty();if(empty)for(int i=body.getChildCount()-1;i>=0;i--){View card=body.getChildAt(i);if("empty".equals(card.getTag())&&!inside(card,getCurrentFocus()))body.removeViewAt(i);}addHomeRow(r);if(empty&&getCurrentFocus()==null)restoreFocus(false);}}
    void updateCatalog(TvRows.Row row){
        if(body==null)return;if(page.equals("shelf:"+row.id)){renderPage(true);return;}if(!page.equals("Home"))return;RowViews old=null;for(RowViews v:visibleRows)if(v.id.equals(row.id)){old=v;break;}if(old==null){appendDiscover();return;}if(row.tiles.isEmpty())return;
        boolean same=old.values.size()==row.tiles.size()+(row.allTiles.size()>row.tiles.size()?1:0);if(same)for(int n=0;n<row.tiles.size();n++)if(!old.values.get(n).key.equals(row.tiles.get(n).key)){same=false;break;}if(same)return;
        int focused=-1;for(int n=0;n<old.tiles.size();n++)if(old.tiles.get(n).hasFocus()){focused=n;break;}
        TvRows.Row display=new TvRows.Row(row.id,row.title,false,false);display.tiles.addAll(row.tiles);display.allTiles.addAll(row.allTiles);
        if(focused>=0&&focused<row.tiles.size()){TvRows.Tile selected=old.values.get(focused);for(TvRows.Tile t:display.tiles)if(t.key.equals(selected.key)){selected=t;break;}final String key=selected.key;display.tiles.removeIf(t->t.key.equals(key));display.tiles.add(Math.min(focused,display.tiles.size()),selected);while(display.tiles.size()>TvUi.ROW_LIMIT)display.tiles.remove(display.tiles.size()-1);}
        int position=visibleRows.indexOf(old),bodyPosition=body.indexOfChild(old.view),y=scroll.getScrollY(),x=((HorizontalScrollView)((LinearLayout)old.view).getChildAt(1)).getScrollX();
        addHomeRow(display);RowViews replacement=visibleRows.remove(visibleRows.size()-1);body.removeView(replacement.view);body.removeView(old.view);body.addView(replacement.view,bodyPosition);visibleRows.set(position,replacement);
        if(focused>=0)replacement.tiles.get(Math.min(focused,replacement.tiles.size()-1)).requestFocus();final RowViews current=replacement;scroll.post(()->{if(page.equals("Home")&&visibleRows.contains(current)){((HorizontalScrollView)((LinearLayout)current.view).getChildAt(1)).scrollTo(x,0);scroll.scrollTo(0,y);}});
    }
    void warmDiscover(){DataStore source=data;catalogs.execute(()->{DiscoveryClient client=new DiscoveryClient(source.context);String[] kinds={"movie","series"};for(String kind:kinds){if(Thread.currentThread().isInterrupted())return;String path="catalog/"+kind+"/top/skip=0.json";try{File file=new File(client.directory,DiscoveryClient.hash(path)+".json");if(file.isFile())publishCatalog(source,kind,new JSONObject(new String(new android.util.AtomicFile(file).readFully(),StandardCharsets.UTF_8)));}catch(Exception ignored){}}
            for(String kind:kinds){if(Thread.currentThread().isInterrupted())return;try{publishCatalog(source,kind,client.read("catalog/"+kind+"/top/skip=0.json",6*3600000L));}catch(Exception ignored){}}
        });}
    void publishCatalog(DataStore source,String kind,JSONObject json){TvRows.Row row=new TvRows.Row("discover:"+kind,kind.equals("movie")?"Discover movies":"Discover TV shows",false,false);for(JSONObject raw:DataStore.objects(json.optJSONArray("metas"))){if(!raw.optString("id").matches("tt[0-9]+"))continue;JSONObject title=DataStore.copy(raw);DataStore.put(title,"noirType",kind);row.add(new TvRows.Tile(title));}ui.post(()->{if(isDestroyed()||data!=source)return;discoveryRows.put(row.id,row);if(active)updateCatalog(row);});}
    void warmCredits(){if(model==null)return;DataStore source=data;if(warmingSource==source)return;warmingSource=source;TvRows local=model;catalogs.execute(()->{Map<String,List<String>> loaded=TvRows.credits(source,local.groups);boolean available=false;try{available=!new PhoneDownloadSettings(source.context).load().optString("manifest").isEmpty();}catch(Exception ignored){}boolean stream=available;ui.post(()->{if(isDestroyed()||source!=data)return;warmingSource=null;boolean changed=canStream!=stream||!credits.equals(loaded);canStream=stream;credits=loaded;if(changed)refreshModel();});});}
    void refreshIfNeeded(){if(data!=NoirApp.data){data=NoirApp.data;renderedRevision=-1;credits=Collections.emptyMap();discoveryRows.clear();memories.clear();openedShelf=null;if(page.startsWith("shelf:"))page="Home";remoteSearchTiles.clear();remoteQuery="";generation++;canStream=false;model=null;renderPage(true);refreshModel();warmDiscover();}else if(renderedRevision!=data.version&&!projecting)refreshModel();}
    void refreshModel(){DataStore source=data;int token=++generation;projecting=true;boolean stream=canStream;Map<String,List<String>> known=credits;source.images.execute(()->{TvRows fresh=new TvRows(source,stream,known);ui.post(()->{if(isDestroyed()||source!=data||token!=generation)return;boolean initial=model==null;model=fresh;projecting=false;renderedRevision=fresh.revision;if(active||initial){if(!initial&&page.equals("Search")&&input!=null)refreshSearch();else renderPage(!initial);}else renderedRevision=-1;if(initial)warmCredits();if(active)refreshIfNeeded();});});}
    void sync(boolean report){if(syncing||!data.paired())return;syncing=true;DataStore source=data;source.network.execute(()->{long before=source.version;boolean online=source.online;String items=source.itemsShared().toString(),settings=source.settings().toString();try{source.sync();}catch(Exception ignored){}boolean changed=online!=source.online||!items.equals(source.itemsShared().toString())||!settings.equals(source.settings().toString());long revision=source.version;ui.post(()->{syncing=false;if(isDestroyed()||source!=data)return;if(changed){if(active)refreshModel();else renderedRevision=-1;}else if(renderedRevision==before)renderedRevision=revision;});});}
    void open(TvRows.Tile tile){Intent intent=new Intent(this,TvDetailActivity.class);if(tile.discover==null)intent.putExtra("group",tile.item.optString("group"));else intent.putExtra("discover",tile.discover.toString());startActivity(intent);}
    void tileMenu(TvRows.Tile tile){LinearLayout panel=column();panel.setPadding(dp(20),dp(12),dp(20),dp(18));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(tile.title()).setView(panel).create();String[] labels={"Play now","Go to title","Mark watched"};TextView first=null;for(int n=0;n<labels.length;n++){final int action=n;TextView b=TvUi.button(this,Loc.t(labels[n]),n==0,()->{dialog.dismiss();if(action==0)play(tile.item);else if(action==1)open(tile);else markWatched(tile.item);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(9);panel.addView(b,p);if(first==null)first=b;}TextView focus=first;dialog.setOnShowListener(d->{dialog.getWindow().setBackgroundDrawable(TvUi.bg(TvUi.PANEL,dp(16)));dialog.getWindow().setLayout(dp(360),-2);focus.requestFocus();});dialog.show();}
    void play(JSONObject item){if(launching)return;String id=item.optString("id");if(!data.localFile(id).isEmpty()){startActivity(new Intent(this,PlayerActivity.class).putExtra("id",id).putExtra("restart",false));data.syncSoon();return;}if(!(data.paired()&&data.online&&item.optBoolean("available"))){if(!PhoneStream.available(this))startActivity(new Intent(this,TvSetupActivity.class));else PhoneStream.start(this,item,false);return;}launching=true;DataStore source=data;source.network.execute(()->{try{source.sync();}catch(Exception ignored){}JSONObject latest=source.item(id);if(latest!=null)try{source.cacheSubtitles(latest);}catch(Exception ignored){}ui.post(()->{launching=false;if(!active||source!=data||isDestroyed())return;if(source.localFile(id).isEmpty()&&!source.online){Toast.makeText(this,Loc.t("PC is offline"),Toast.LENGTH_SHORT).show();return;}startActivity(new Intent(this,PlayerActivity.class).putExtra("id",id).putExtra("restart",false));});});}
    @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getKeyCode()==KeyEvent.KEYCODE_SEARCH){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){showPage("Search",true);if(input!=null){input.requestFocus();input.performClick();}}return true;}return super.dispatchKeyEvent(e);}
    @Override public void onBackPressed(){hideKeyboard();if(!page.equals("Home")){showPage("Home",true);return;}if(!visibleRows.isEmpty()&&!memory().row.equals(visibleRows.get(0).id)){RowViews first=visibleRows.get(0);memory().index=0;memory().row=first.id;memory().tile=first.values.get(0).key;first.tiles.get(0).requestFocus();scroll.scrollTo(0,0);return;}finish();}
    final class StableScroll extends ScrollView {StableScroll(){super(TvActivity.this);}@Override public boolean requestChildRectangleOnScreen(View child,Rect rectangle,boolean immediate){return false;}}

    // PhoneSmart's check-off operations and date rules, without its phone-only UI/reward host.
    void markWatched(JSONObject item){JSONObject fresh=data.item(item.optString("id"));if(fresh!=null)item=fresh;final JSONObject focus=item;if(DataStore.watched(focus))return;List<JSONObject> earlier=new ArrayList<>();List<JSONObject> group=model.index.get(focus.optString("group"));if(group!=null&&!focus.optBoolean("movie")&&focus.optInt("season")>0)for(JSONObject i:group)if(i.optInt("season")>0&&PhoneSmart.before(i,focus)&&!DataStore.watched(i)&&airs(i)<=System.currentTimeMillis())earlier.add(i);
        if(earlier.isEmpty()){logWatched(Collections.singletonList(focus),"Just now",0);afterMark(focus);return;}
        new AlertDialog.Builder(this).setTitle(Loc.t("Also mark earlier episodes?")).setMessage(PhoneSmart.range(earlier)).setNegativeButton(Loc.t("Just this episode"),(d,w)->{logWatched(Collections.singletonList(focus),"Just now",0);afterMark(focus);}).setPositiveButton(Loc.t("Earlier episodes too"),(d,w)->askWhen((when,day)->{if(when.equals("Just now")){List<JSONObject> all=new ArrayList<>(earlier);all.add(focus);logWatched(all,when,day);}else{logWatched(earlier,when,day);logWatched(Collections.singletonList(focus),"Just now",0);}afterMark(focus);})).show();
    }
    long airs(JSONObject item){long at=DataStore.date(item.optString("airsAt"));if(at>0)return at;JSONObject schedules=model.settings.optJSONObject("schedules");for(JSONObject ep:DataStore.objects(schedules==null?null:schedules.optJSONArray(item.optString("group"))))if(ep.optInt("season")==item.optInt("season")&&ep.optInt("episode")==item.optInt("episode"))return DataStore.date(ep.optString("airsAt"));return 0;}
    void askWhen(java.util.function.BiConsumer<String,Long> chosen){String[] labels=new String[PhoneSmart.WHEN.length];for(int n=0;n<labels.length;n++)labels[n]=Loc.t(PhoneSmart.WHEN[n]);new AlertDialog.Builder(this).setTitle(Loc.t("When did you watch the earlier ones?")).setItems(labels,(d,n)->{if(n==3){year("Around which year?",1950,y->chosen.accept("Around a year",LocalDate.of(y,7,1).toEpochDay()));return;}if(n==4){year("From which year?",1950,from->year("Until which year?",from,to->chosen.accept("Over a period:"+from+"-"+to,0L)));return;}if(n==2){LocalDate today=LocalDate.now();DatePickerDialog picker=new DatePickerDialog(this,(v,y,m,day)->chosen.accept("Pick a date",LocalDate.of(y,m+1,day).toEpochDay()),today.getYear(),today.getMonthValue()-1,today.getDayOfMonth());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();}else chosen.accept(PhoneSmart.WHEN[n],0L);}).setNegativeButton(Loc.t("Cancel"),null).show();}
    void year(String title,int earliest,java.util.function.IntConsumer chosen){int now=LocalDate.now().getYear();String[] years=new String[now-Math.max(1950,earliest)+1];for(int n=0;n<years.length;n++)years[n]=String.valueOf(now-n);new AlertDialog.Builder(this).setTitle(Loc.t(title)).setItems(years,(d,n)->chosen.accept(now-n)).show();}
    double runtime(JSONObject item){JSONObject p=item.optJSONObject("progress");double seconds=p==null?0:p.optDouble("duration",0);if(seconds<60)seconds=item.optDouble("duration",0);return seconds>=60?seconds:item.optBoolean("movie")?6600:2580;}
    void logWatched(List<JSONObject> items,String when,long picked){List<JSONObject> sorted=new ArrayList<>(items);sorted.sort(Comparator.comparingInt((JSONObject i)->i.optInt("season")).thenComparingInt(i->i.optInt("episode")));long now=System.currentTimeMillis(),cursor=when.equals("Pick a date")||when.equals("Around a year")?LocalDate.ofEpochDay(picked).atTime(22,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli():now;cursor=Math.min(cursor,now);long start=0,end=0;if(when.startsWith("Over a period:")){String[] years=when.substring(14).split("-");start=LocalDate.of(Integer.parseInt(years[0]),1,1).atTime(21,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();end=Math.min(now,LocalDate.of(Integer.parseInt(years[1]),12,31).atTime(21,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli());}long[] at=new long[sorted.size()];boolean[] unknown=new boolean[at.length],approx=new boolean[at.length];for(int n=sorted.size()-1;n>=0;n--){JSONObject i=sorted.get(n);long aired=airs(i);if(end>0){at[n]=start+(long)((end-start)*((n+.5)/sorted.size()));approx[n]=true;continue;}approx[n]=when.equals("Around a year");switch(when){case "When they aired":if(aired>0&&aired<=now)at[n]=aired;else unknown[n]=true;approx[n]=true;break;case "Don't remember":unknown[n]=true;break;default:at[n]=Math.max(cursor,aired>0&&aired<=now?aired:0);}cursor-=(long)(runtime(i)*1000);}for(int n=0;n<sorted.size();n++){JSONObject i=sorted.get(n);String id=data.item(i.optString("id"))!=null?i.optString("id"):data.rememberPhoneItem(i).optString("id");data.approximate=approx[n];data.mark(id,true,unknown[n]?0:at[n],unknown[n]);}data.syncSoon();}
    void afterMark(JSONObject focus){if(!focus.optBoolean("movie")){List<JSONObject> g=model.index.get(focus.optString("group"));boolean all=g!=null;JSONObject specials=model.settings;JSONArray included=specials.optJSONArray("includeSpecials");boolean include=HomeLayout.jsonValues(included).contains(focus.optString("group"));int released=0;if(g!=null)for(JSONObject i:g)if(i.optInt("episode")>0&&(i.optInt("season")>0||include)&&airs(i)<=System.currentTimeMillis()){released++;JSONObject fresh=data.item(i.optString("id"));if(fresh==null||!DataStore.watched(fresh))all=false;}JSONObject states=model.settings.optJSONObject("showStates");if(all&&released>0&&states!=null&&states.optString(focus.optString("group")).equals("Ended")){JSONObject op=data.operation(focus.optString("id"),"status");DataStore.put(op,"status","Finished");data.queue(op);data.syncSoon();}}Toast.makeText(this,Loc.t("Marked watched"),Toast.LENGTH_SHORT).show();refreshModel();}
